// 🎯 Cal.com data extractor with proper URL extraction
const body = items[0].json;

// 🐛 Debug: Log the structure to understand the data
console.log("=== FULL CAL.COM PAYLOAD ===");
console.log(JSON.stringify(body, null, 2));

// ✅ Extract data based on Cal.com webhook structure
const eventId = body.id || body.uid || 'unknown';
const eventName = body.type || body.eventType?.title || 'Meeting';
const eventStartTime = body.startTime;
const eventEndTime = body.endTime;

// 👤 Extract attendee information (first attendee)
const attendee = body.attendees?.[0] || {};
const inviteeName = attendee.name || 'Guest';
const inviteeEmail = attendee.email || '';
const inviteeTimezone = attendee.timeZone || body.timeZone || 'UTC';

// 🏢 Extract location information
let eventLocation = 'Not specified';
if (body.location) {
    eventLocation = body.location;
} else if (body.metadata?.videoCallUrl) {
    eventLocation = 'Online Meeting';
}

// 🔗 Construct reschedule and cancel URLs using uid
const uid = body.uid || body.id;
const rescheduleUrl = uid ? `https://app.cal.com/booking/${uid}?reschedule=true` : '';
const cancelUrl = uid ? `https://app.cal.com/booking/${uid}?cancel=true` : '';

// 📝 Extract questions and answers from responses
let questions = [];
let actualQuestions = [];
const systemFields = {};

if (body.responses && typeof body.responses === 'object') {
    Object.keys(body.responses).forEach(key => {
        const answer = body.responses[key];
        const questionObj = {
            question: key,
            answer: answer
        };

        questions.push(questionObj);

        // Check for special fields
        const questionLower = key.toLowerCase();
        if (questionLower.includes('linkedin') || questionLower.includes('profile')) {
            systemFields.linkedInUrl = answer || '';
        } else {
            actualQuestions.push(questionObj);
        }
    });
}

// 📝 Create questions text from actual questions
const questionsText = actualQuestions.map(qa => `Q: ${qa.question}\nA: ${qa.answer.value}`).join('\n\n');

// 🎥 Extract meeting URI from metadata
const meetingUri = body.metadata?.videoCallUrl || body.location || '';

// 📧 Extract host email
const eventHostEmail = body.organizer?.email || '[USER_EMAIL]';

// ✅ Return data with proper Cal.com structure
return [{
    json: {
        // Event data using Cal.com paths
        eventId: eventId,
        eventName: eventName,
        eventStartTime: eventStartTime,
        eventEndTime: eventEndTime,
        eventLocation: eventLocation,

        // Invitee data
        inviteeName: inviteeName,
        inviteeEmail: inviteeEmail,
        inviteeTimezone: inviteeTimezone,

        // URLs constructed from uid
        cancelUrl: cancelUrl,
        rescheduleUrl: rescheduleUrl,

        // Host email
        eventHostEmail: eventHostEmail,

        // Debug info for Cal.com
        debugInfo: {
            hasId: !!body.id,
            hasUid: !!body.uid,
            hasAttendees: !!(body.attendees && body.attendees.length > 0),
            hasResponses: !!body.responses,
            hasMetadata: !!body.metadata,
            startTimeFound: !!eventStartTime,
            locationFound: !!eventLocation,
            timezoneFound: !!inviteeTimezone,
            cancelUrlConstructed: !!cancelUrl,
            rescheduleUrlConstructed: !!rescheduleUrl,
            webhookStructure: Object.keys(body || {}),
            attendeeKeys: Object.keys(attendee || {}),
            responsesKeys: body.responses ? Object.keys(body.responses) : []
        },

        // Questions and custom fields
        inviteeQuestions: actualQuestions,
        questionsText: questionsText,
        allQuestions: questions,

        // Custom fields
        linkedInUrl: systemFields.linkedInUrl,

        // Booking data
        bookingCreatedAt: body.createdAt || body.created_at,
        meetingUri: meetingUri
    }
}];

// Process all input items in runOnceForAllItems mode
return items.map(item => {
  // Get the raw string output from the LLM
  const rawOutput = item.json.output;
  // Remove the markdown code block markers (```json and ```)
  const cleanedString = rawOutput.replace(/```json\n|```/g, '');
  // Parse the cleaned string into a real JSON object
  const parsedJson = JSON.parse(cleanedString);
  // Return the usable JSON object for the next nodes
  return {
    json: parsedJson
  };
});
